import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.CRFziyHp.js";const g=JSON.parse('{"title":"可选基础设施","description":"","frontmatter":{},"headers":[],"relativePath":"ops/docker-infra.md","filePath":"ops/docker-infra.md","lastUpdated":1785013113000}'),r={name:"ops/docker-infra.md"};function o(l,a,n,d,h,c){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="可选基础设施" tabindex="-1">可选基础设施 <a class="header-anchor" href="#可选基础设施" aria-label="Permalink to &quot;可选基础设施&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>介绍如何通过 Docker 可选启动 <strong>Meilisearch</strong>（搜索）与 <strong>Gorse</strong>（推荐）等组件；<strong>不包含</strong> 应用主程序、MySQL、Redis。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>服务器已安装 Docker 与 Docker Compose（或 <code>docker compose</code> 插件）。</li><li>灵萌应用已至少启动过一次，以便释放部署文件到服务器目录。</li><li>由 <strong>运维</strong> 执行命令；管理员只需知道「启用了什么」并在后台 <strong>搜索索引</strong> 中查看状态。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>管理员 <strong>无需</strong> 在后台填写 Docker 参数。运维完成部署后，您只需：</p><ol><li>打开 <strong>系统监控 → 搜索索引</strong>，确认 Meilisearch 状态为在线</li><li>若启用推荐，打开 <strong>系统监控 → 相关推荐评估</strong> 查看是否连通</li><li>搜索功能异常时，将 <strong>搜索索引</strong> 页错误截图发给运维</li></ol><p>密钥一致性（Meilisearch Master Key、Gorse API Key）须与服务器配置文件相同，由运维维护，管理员不要自行修改生产密钥。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>Docker 栈为 <strong>全站级</strong>，无区域菜单。启用后所有区域共享同一搜索 / 推荐集群。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><p><strong>运维侧：</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> static/deploy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 首次：编辑密钥与端口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 启动栈，等价于 docker compose up -d</span></span></code></pre></div><p><strong>管理员侧：</strong></p><ul><li><strong>系统监控 → 搜索索引</strong> 显示已连接、文档数 &gt; 0</li><li>客户端搜索能命中新内容（见 <a href="/features/search">搜索与推荐</a>）</li></ul><p>停止栈（运维执行）：在同一目录运行 <code>bash down.sh</code>。</p><h2 id="包含与不包含" tabindex="-1">包含与不包含 <a class="header-anchor" href="#包含与不包含" aria-label="Permalink to &quot;包含与不包含&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>默认端口</th><th>用途</th></tr></thead><tbody><tr><td>Meilisearch</td><td>7700</td><td>全文搜索</td></tr><tr><td>Gorse</td><td>8087 / 8088</td><td>相关推荐</td></tr><tr><td>NebulaGraph</td><td>9669</td><td>社交图（高级，可选）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Docker Compose <strong>不提供</strong> MySQL、Redis 和灵萌应用本身，这些须单独安装或使用云服务。</p></div><p>同机部署多套站点时，修改 <code>.env</code> 中的端口与栈名称，避免冲突（详见 <code>static/deploy/.env.example</code> 说明）。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>up.sh 找不到</strong></p><ul><li>先启动灵萌应用，部署文件会展开到运行目录下的 <code>static/deploy/</code>。</li></ul><p><strong>搜索索引仍离线</strong></p><ul><li>运维检查容器是否运行：<code>docker ps</code></li><li>Master Key 是否与 <code>config.yaml</code> 中 meilisearch 段一致</li></ul><p><strong>可以不装 Meilisearch 吗</strong></p><ul><li>可以；小规模可用内置能力。用户量大或搜索延迟高时再启用 Docker 版。</li></ul><p><strong>Gorse 必须装吗</strong></p><ul><li>否；仅当需要个性化 <strong>相关推荐</strong> 时可选安装。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/search">搜索与推荐</a></li><li><a href="/ops/monitoring">系统监控入口</a></li></ul>`,32)])])}const k=e(r,[["render",o]]);export{g as __pageData,k as default};
